{"path": "notify/notify.go", "old": "// flush sends every due reminder once. It holds d.mu so flushes never
// overlap.
func (d *Dispatcher) flush(ctx context.Context) {
	d.mu.Lock()
	defer d.mu.Unlock()
	for _, r := range d.store.Due(d.now()) {
		u, err := d.store.User(r.UserID)
		if err != nil {
			continue
		}
		if err := d.SendNow(ctx, u, r); err != nil {
			d.retries[r.ID]++
			d.log.Warn("notify: send failed", "reminder", r.ID, "attempt", d.retries[r.ID], "err", err)
			continue
		}
		delete(d.retries, r.ID)
		d.store.MarkSent(r.ID)
	}
}", "new": "// flush sends every due reminder once. It holds d.flushMu so flushes never
// overlap. It must not hold d.mu while calling the store: the store calls
// forget, which takes d.mu, while holding its own lock.
func (d *Dispatcher) flush(ctx context.Context) {
	d.flushMu.Lock()
	defer d.flushMu.Unlock()
	for _, r := range d.store.Due(d.now()) {
		u, err := d.store.User(r.UserID)
		if err != nil {
			continue
		}
		if err := d.SendNow(ctx, u, r); err != nil {
			d.mu.Lock()
			d.retries[r.ID]++
			attempt := d.retries[r.ID]
			d.mu.Unlock()
			d.log.Warn("notify: send failed", "reminder", r.ID, "attempt", attempt, "err", err)
			continue
		}
		d.mu.Lock()
		delete(d.retries, r.ID)
		d.mu.Unlock()
		d.store.MarkSent(r.ID)
	}
}"}

