func TestGetDeletedReminderIsNotFound(t *testing.T) {
	s := New(func() time.Time { return time.Unix(0, 0) })
	r := s.Create("u1", "gone soon", time.Unix(100, 0), nil)
	if err := s.Delete(r.ID); err != nil {
		t.Fatal(err)
	}
	got, err := s.Get(r.ID)
	if !errors.Is(err, ErrNotFound) {
		t.Fatalf("Get deleted reminder: err = %v, want ErrNotFound", err)
	}
	if got != nil {
		t.Errorf("Get deleted reminder: got %+v, want nil", got)
	}
}

func TestListOffsetPastEnd(t *testing.T) {
	s := New(func() time.Time { return time.Unix(0, 0) })
	for range 3 {
		s.Create("u1", "x", time.Unix(100, 0), nil)
	}
	if got := s.List("u1", 4, 2); len(got) != 0 {
		t.Errorf("List past end = %d reminders, want 0", len(got))
	}
	if got := s.List("u1", 2, 2); len(got) != 1 {
		t.Errorf("List from 2 = %d reminders, want 1", len(got))
	}
}

func TestImportUsersGetsDefaultPrefs(t *testing.T) {
	s := New(func() time.Time { return time.Unix(0, 0) })
	if n := s.ImportUsers([]User{{ID: "u1", Token: "tok"}}); n != 1 {
		t.Fatalf("ImportUsers = %d, want 1", n)
	}
	u, err := s.User("u1")
	if err != nil {
		t.Fatal(err)
	}
	if u.Prefs == nil {
		t.Fatal("imported user has nil Prefs")
	}
	if u.Prefs.Channel != "email" {
		t.Errorf("imported user channel = %q, want email", u.Prefs.Channel)
	}
}
"}

